import{_ as o,C as r,o as a,c as n,a2 as t,E as i}from"./chunks/framework.9yf7n3zg.js";const h="/guide/media/how-a-story-is-read-page.webp",d="/guide/media/how-a-story-is-read-strip.webp",m=JSON.parse('{"title":"How a story is read","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-a-story-is-read.md","filePath":"guide/how-a-story-is-read.md","lastUpdated":1792171429000}'),l={name:"guide/how-a-story-is-read.md"};function g(p,e,c,y,f,u){const s=r("Clip");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="how-a-story-is-read" tabindex="-1">How a story is read <a class="header-anchor" href="#how-a-story-is-read" aria-label="Permalink to &quot;How a story is read&quot;">​</a></h1><p>Every view of a story (the plot grid, the threads, the Graph, the manuscript) is a reading of the same files. <strong>How this story is read</strong> is the page that shows that reading on your own story: for each rule Leathercase reads by, what it found in your folder, and a fix where something looks off. This page explains each part of it, each question it can ask, and what each fix does.</p><p>A fix writes only Leathercase&#39;s own files, such as an ignore pattern in the story&#39;s settings or a note Leathercase owns, or it opens your note at the right spot for you to change. Your notes are never written.</p><h2 id="opening-it" tabindex="-1">Opening it <a class="header-anchor" href="#opening-it" aria-label="Permalink to &quot;Opening it&quot;">​</a></h2><p><strong>How this story is read</strong> is a page about the story rather than a view of it. Open it from:</p><ul><li>the breadcrumb&#39;s view menu (the view&#39;s name with a small arrow), below the views;</li><li>the <strong>⋯</strong> on the open story&#39;s row in the sidebar, or the breadcrumb&#39;s story menu;</li><li><strong>How this story is read</strong> in the View menu, or typed in the find field;</li><li><strong>N unsorted</strong>, in amber, in a view&#39;s state line;</li><li><strong>Why? See how this story is read</strong>, in a view that found nothing to show;</li><li><strong>Show me</strong> on the notice about a story declared before roles;</li><li><strong>How it is read</strong>, beside <strong>Files</strong> on the story&#39;s settings page.</li></ul><p>The breadcrumb then reads <code>Stories › The Lamp at Ferrol › How this story is read</code>. Leaving it, by choosing a view, goes back to the view you were on.</p><p><img src="'+h+'" alt="How this story is read on The Lamp at Ferrol, with What looks off at the top and the rules below" width="1130" height="965" loading="lazy"></p><h2 id="the-state-line-and-the-side-column" tabindex="-1">The state line and the side column <a class="header-anchor" href="#the-state-line-and-the-side-column" aria-label="Permalink to &quot;The state line and the side column&quot;">​</a></h2><p>The state line at the top sums up the reading: <strong>14 notes read · 32 scenes written · nothing looks off</strong>, or <strong>1 thing looks off</strong>, <strong>3 things look off</strong>. While the folder is read it says <strong>reading…</strong>.</p><p>The side column says what the page is: <strong>Each rule Leathercase reads a story by, with what it found in this folder. A fix writes only Leathercase&#39;s own files, or opens your note at the spot.</strong> and <strong>What Leathercase read from your folder, as it found it. Nothing here is written back. The patterns that choose these files live in Story settings.</strong> Its button, <strong>The shape of a story folder</strong>, opens the guide&#39;s page on laying out a story folder (see <a href="#the-shape-of-a-story-folder">the end of this page</a>).</p><p>Each rule below is a section with its title, a count beside it, a line that states the rule, and what it found. Long lists scroll within their box. Wherever a file is listed with <strong>Open</strong>, the button opens it in your writing software.</p><h2 id="what-looks-off" tabindex="-1">What looks off <a class="header-anchor" href="#what-looks-off" aria-label="Permalink to &quot;What looks off&quot;">​</a></h2><p>The first section lists everything that needs you, each with an amber dot and its fix. When there is nothing it says <strong>Nothing looks off. Each rule below says what it found.</strong> When no file matched the story&#39;s patterns at all it says <strong>No note matched the story&#39;s patterns. Check the folder and the patterns in Story settings.</strong> with <strong>Open story settings</strong>.</p><p>The findings, in the order they appear:</p><table tabindex="0"><thead><tr><th>Finding</th><th>Example</th><th>Fix</th></tr></thead><tbody><tr><td>A story declared before roles</td><td><strong>Leathercase now reads as scenes only the prose you declare. Today 13 notes are read as scenes, in Act I - The Dark Lamp, Act II - Salvage, Act III - Light.</strong></td><td><strong>Keep this reading</strong></td></tr><tr><td>Unsorted files</td><td><strong>2 notes say type: symbol. What are they?</strong></td><td>A choice, then <strong>Answer</strong>, or <strong>Don&#39;t ask again</strong></td></tr><tr><td>A note renamed</td><td><strong>Nora looks renamed to Nora Vidal: its note&#39;s text is the same. Should Leathercase&#39;s own files follow the new name?</strong></td><td><strong>Yes, follow Nora Vidal</strong> or <strong>No, they are different</strong></td></tr><tr><td>A name Leathercase&#39;s files still use</td><td><strong>Relationships.md names Nora, and no note of the story answers to that name.</strong></td><td><strong>Open Relationships.md</strong>, or <strong>Open the story&#39;s settings</strong></td></tr><tr><td>Work read as story</td><td><strong>2 notes in _Work are read as story. A folder of memos or research is work about the story, not the story.</strong></td><td><strong>Leave _Work/** out</strong></td></tr><tr><td>A type and a folder that disagree</td><td><strong>Places/Inés.md sits in a folder of places, but its type says character. The type wins.</strong></td><td><strong>Open the note at its type</strong></td></tr><tr><td>A long note with no heading</td><td><strong>Novel.md has 4,200 words and no heading, so it is read as one scene. A heading per scene gives each its own row on the grid.</strong></td><td><strong>Open the note</strong></td></tr><tr><td>A name with no note</td><td><strong>Rosalía is named 12 times and has no note.</strong></td><td><strong>Make a character note</strong> or <strong>Make a place note</strong></td></tr></tbody></table><p>Each is explained below.</p><h3 id="a-story-declared-before-roles" tabindex="-1">A story declared before roles <a class="header-anchor" href="#a-story-declared-before-roles" aria-label="Permalink to &quot;A story declared before roles&quot;">​</a></h3><p>Leathercase now reads as scenes only the files you declare as prose (see <a href="/guide/guide/declare-a-story#the-seven-roles">the seven roles</a>). A story declared before that change still reads the old way, where whatever nothing claimed was prose, and opening a story never writes anything, so the story keeps its old reading until you say.</p><p>The notice says how many notes are read as scenes today, and where. When some would stop being scenes, it says so: <strong>2 notes will no longer be read as scenes: Ideas/Sea.md, Symbols/Lamp.md.</strong> When nothing is read as prose yet, it says <strong>Leathercase now reads as scenes only the prose you declare. Nothing in this story is read as prose yet.</strong></p><p><strong>Keep this reading</strong> writes today&#39;s prose into the story&#39;s <code>Story.json</code> as declared. From then on a file added where nothing claims it waits, unsorted, instead of becoming a scene. The notice comes back each time until you keep the reading.</p><h3 id="questions-about-unsorted-files" tabindex="-1">Questions about unsorted files <a class="header-anchor" href="#questions-about-unsorted-files" aria-label="Permalink to &quot;Questions about unsorted files&quot;">​</a></h3><p>A file is unsorted when nobody has said what it is, or when its <code>type:</code> is a word the story does not know. It is never a scene. Leathercase groups unsorted files and asks one question per group:</p><ul><li>by type: <strong>2 notes say type: symbol. What are they?</strong></li><li>by folder: <strong>3 notes in Ideas/ are not sorted. What does the folder hold?</strong></li><li>at the top: <strong>1 note at the top of the story&#39;s folder is not sorted. What is it?</strong></li></ul><p>Beside the question, <strong>Choose what they are…</strong> opens the answers:</p><table tabindex="0"><thead><tr><th>Answer</th><th>Offered for</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Things that recur, a kind of their own</strong></td><td>Every group</td><td>Makes a kind of your own, found in the prose by its names. A <strong>Named</strong> field appears, filled from the type word or the folder&#39;s name, such as <em>Symbol</em> or <em>Clue</em>.</td></tr><tr><td><strong>Things that recur, found by their images too (symbols, motifs)</strong></td><td>Every group</td><td>Makes a kind of your own of the symbol quality, also found by the images you list for each note. <strong>Named</strong> appears too.</td></tr><tr><td><strong>The story&#39;s prose</strong></td><td>Every group</td><td>The files become prose and make scenes</td></tr><tr><td><strong>Characters</strong>, <strong>Places</strong>, <strong>Items</strong>, <strong>Factions</strong>, <strong>Events</strong></td><td>A folder, or the top of the story</td><td>The folder holds that kind</td></tr><tr><td><strong>Plans (outline, synopsis)</strong>, <strong>Records (chronology, style sheet)</strong>, <strong>Work notes (journal, feedback)</strong>, <strong>Research</strong>, <strong>Scraps (cut scenes)</strong></td><td>Every group</td><td>The files take that role</td></tr><tr><td>A kind of your own, by name</td><td>Every group, once the story has some</td><td>The files join it</td></tr></tbody></table><p>Nothing is chosen until you choose, so <strong>Answer</strong> never writes a guess; it stays greyed out until you pick. <strong>Answer</strong> writes your answer into the story&#39;s <code>Story.json</code>. One answer settles every file in the group, and every file written later that says the same type or sits in the same folder.</p><p><strong>Don&#39;t ask again</strong> leaves the files unsorted and never asks about that group again. They still count in the state line&#39;s <strong>N unsorted</strong>.</p><p>A kind of your own appears afterwards in the Graph, counted in the shape of the story, in the Tags view under <strong>Kinds of your own</strong>, and in the folder selects of the story&#39;s settings. See <a href="/guide/guide/declare-a-story#kinds-of-your-own">Kinds of your own</a>.</p><h3 id="renames-and-names-leathercase-s-files-still-use" tabindex="-1">Renames, and names Leathercase&#39;s files still use <a class="header-anchor" href="#renames-and-names-leathercase-s-files-still-use" aria-label="Permalink to &quot;Renames, and names Leathercase&#39;s files still use&quot;">​</a></h3><p>When you rename a character&#39;s note in your writing app, Leathercase asks whether it is a rename, here and over the story&#39;s views. <strong>Yes, follow Nora Vidal</strong> carries Leathercase&#39;s own files to the new name; <strong>No, they are different</strong> is never asked again. When one of Leathercase&#39;s files names someone no note answers to, the finding offers to open that file at the line, or the story&#39;s settings when the name is in <code>Story.json</code>. The full account is on <a href="/guide/guide/homes-and-stories#renamed-notes">Homes and stories</a>.</p><h3 id="work-read-as-story" tabindex="-1">Work read as story <a class="header-anchor" href="#work-read-as-story" aria-label="Permalink to &quot;Work read as story&quot;">​</a></h3><p>Memos, research and reviews talk about the cast in ways that are not scenes. When notes read as prose sit in a folder whose name starts with <code>_</code> (such as <code>_Work</code>), or in a folder named for work about the story (Work, Memos, Research, Reviews, Archive, Templates, Trash, and the same words in the other languages Leathercase reads), Leathercase says so.</p><p><strong>Leave _Work/** out</strong> adds the pattern <code>_Work/**</code> to the files the story leaves out, in its settings. The story is read again: the memos leave the Graph, the grid, the threads and the manuscript, and they are listed under <a href="#notes-left-out">Notes left out</a> as <strong>left out by _Work/**</strong>. The memo&#39;s file is unchanged. A pattern already in the story&#39;s settings is never offered twice. To take it back, remove the pattern under <strong>Advanced: the patterns</strong> in <a href="/guide/guide/story-settings">Story settings</a>.</p><h3 id="a-type-and-a-folder-that-disagree" tabindex="-1">A type and a folder that disagree <a class="header-anchor" href="#a-type-and-a-folder-that-disagree" aria-label="Permalink to &quot;A type and a folder that disagree&quot;">​</a></h3><p>A note in <code>Places/</code> whose properties say <code>type: character</code> is read as a character: its type wins over its folder. Leathercase points it out in case one of the two is a mistake. <strong>Open the note at its type</strong> opens the note in your writing software at the line that says its type, so you can change whichever is wrong.</p><h3 id="a-long-note-with-no-heading" tabindex="-1">A long note with no heading <a class="header-anchor" href="#a-long-note-with-no-heading" aria-label="Permalink to &quot;A long note with no heading&quot;">​</a></h3><p>Leathercase splits prose into scenes only at headings. A prose note of 1,500 words or more with no heading is read as one scene, which usually means a whole chapter is one row on the grid. <strong>Open the note</strong> opens it, so you can give each scene its own heading. Leathercase never splits at <code>---</code> or blank lines.</p><h3 id="a-name-with-no-note" tabindex="-1">A name with no note <a class="header-anchor" href="#a-name-with-no-note" aria-label="Permalink to &quot;A name with no note&quot;">​</a></h3><p>A name the prose uses eight times or more with no note of its own is raised here, up to five of them, the most named first; every other such name is listed under <a href="#names-without-a-note">Names without a note</a>.</p><ul><li><strong>Make a character note</strong> makes a note for the name, owned by Leathercase, in the story&#39;s <code>suite</code> folder, and opens it in the Graph for you to fill.</li><li><strong>Make a place note</strong> does the same as a place.</li></ul><p>The note is Leathercase&#39;s file, not yours: nothing is added to your own folders.</p><h2 id="notes-typed-as-the-cast" tabindex="-1">Notes typed as the cast <a class="header-anchor" href="#notes-typed-as-the-cast" aria-label="Permalink to &quot;Notes typed as the cast&quot;">​</a></h2><p><strong>A note is a character, place, item, faction or event by the type in its properties, or by the folder it sits in. The type wins.</strong></p><p>Each typed note is listed by name, with its kind and how it was typed: <strong>character · by its type</strong>, <strong>place · by its folder</strong>, or <strong>character · by what you said its folder holds</strong>. When there are none: <strong>No note is typed yet. Keep character notes in a Characters folder, or write type: character in a note&#39;s properties.</strong></p><h2 id="notes-read-as-story" tabindex="-1">Notes read as story <a class="header-anchor" href="#notes-read-as-story" aria-label="Permalink to &quot;Notes read as story&quot;">​</a></h2><p><strong>Only the notes declared as the story&#39;s prose. Their headings split them into scenes; a note with prose and no heading is one scene.</strong></p><p>Each prose note is listed by its path, with what it gave: <strong>3 scenes, 4 links, 2 relationships</strong>, or <strong>no heading: read as one scene</strong>, and <strong>Open</strong>. When there are none: <strong>No note is read as story yet.</strong></p><p>A file nothing claims is not story; it waits under <a href="#unsorted">Unsorted</a> until you say what it is.</p><h2 id="plans-records-work-notes-research-and-kinds-of-your-own" tabindex="-1">Plans, records, work notes, research and kinds of your own <a class="header-anchor" href="#plans-records-work-notes-research-and-kinds-of-your-own" aria-label="Permalink to &quot;Plans, records, work notes, research and kinds of your own&quot;">​</a></h2><p><strong>Notes about the story that are not its prose: they never make scenes. Their own type: line or their folder says what they are.</strong></p><p>Each is listed by path with its role, such as <strong>Plans (outline, synopsis)</strong>, <strong>Research</strong> or the name of your own kind, and <strong>Open</strong>. When there are none: <strong>None.</strong></p><h2 id="unsorted" tabindex="-1">Unsorted <a class="header-anchor" href="#unsorted" aria-label="Permalink to &quot;Unsorted&quot;">​</a></h2><p><strong>Files nothing claims, or whose type: the story does not know. They are never scenes. Say what a folder holds above, or in Story settings.</strong></p><p>Each is listed by path with <strong>unsorted</strong>, or <strong>unsorted · type: symbol</strong> when it gives a type the story does not know, and <strong>Open</strong>. When there are none: <strong>None: every file is sorted.</strong></p><h2 id="notes-left-out" tabindex="-1">Notes left out <a class="header-anchor" href="#notes-left-out" aria-label="Permalink to &quot;Notes left out&quot;">​</a></h2><p><strong>Files under the story&#39;s folder that are not read as story, and why.</strong> Each is listed by path with its reason:</p><table tabindex="0"><thead><tr><th>Reason</th><th>When</th></tr></thead><tbody><tr><td><strong>left out by _Work/**</strong></td><td>A pattern in the story&#39;s settings leaves it out</td></tr><tr><td><strong>Leathercase&#39;s own file</strong></td><td>It is in a <code>suite</code> folder</td></tr><tr><td><strong>the story&#39;s note, read for its settings</strong></td><td>A project note, such as the one the Creative Writer plugin made, read for its settings and not as prose</td></tr><tr><td><strong>its properties say creative-writer: false</strong></td><td>The note opted out in its properties</td></tr><tr><td><strong>a format Leathercase does not read yet</strong></td><td>A file the patterns match but Leathercase cannot read</td></tr></tbody></table><p>Files no pattern reads, such as images, are counted rather than listed: <strong>12 other files no pattern reads, such as images</strong>. When nothing is left out: <strong>Nothing under the story&#39;s folder is left out.</strong></p><h2 id="other-names" tabindex="-1">Other names <a class="header-anchor" href="#other-names" aria-label="Permalink to &quot;Other names&quot;">​</a></h2><p><strong>Names the prose may use for someone with a note: from the note&#39;s aliases, or confirmed in the Graph and kept in Story settings.</strong></p><p>Each is listed as <strong>Nora is Nora Vidal</strong>, with where it comes from: <strong>the note</strong> (its <code>aliases:</code> property) or <strong>Story settings</strong> (a name you confirmed in the Graph). When there are none: <strong>No other names yet.</strong> See <a href="/guide/guide/graph">Graph</a> and <a href="/guide/reference/front-matter">Front matter</a>.</p><h2 id="names-without-a-note" tabindex="-1">Names without a note <a class="header-anchor" href="#names-without-a-note" aria-label="Permalink to &quot;Names without a note&quot;">​</a></h2><p><strong>Names the prose uses three times or more with no note of their own. The Graph shows them dashed; a fix above makes a note for the ones named most.</strong></p><p>Each is listed with its count, such as <strong>5 mentions</strong>. When there are none: <strong>Every name the prose uses often has a note.</strong> In the Graph you can say what such a name is, another name for someone, or not a name at all.</p><h2 id="the-grid-file" tabindex="-1">The grid file <a class="header-anchor" href="#the-grid-file" aria-label="Permalink to &quot;The grid file&quot;">​</a></h2><p><strong>The plot grid is its own file, PlotGrid.md, made from the story the first time it was read: the scenes as rows, linked to the story&#39;s files, and the scenes the writer planned. It replaced Outline.md, whose planned scenes it carried in.</strong></p><p>It shows the file&#39;s path and <strong>every planned scene is written</strong>, or <strong>2 scenes planned, not yet written</strong>. Before the grid has opened once: <strong>No grid file yet. It is made the first time the plot grid opens.</strong> In practice the file is made the first time any of the story&#39;s views reads it, since one reading serves the grid, the threads and the Graph. The file is <code>PlotGrid.md</code> in the story&#39;s <code>suite/</code> folder; <strong>New scene</strong>, <strong>Plan a scene</strong> and beat cards sent to the grid write their planned scenes into it, and <code>Outline.md</code> is never written. See <a href="/guide/guide/plot-grid">Plot grid</a>.</p><h2 id="the-shape-of-a-story-folder" tabindex="-1">The shape of a story folder <a class="header-anchor" href="#the-shape-of-a-story-folder" aria-label="Permalink to &quot;The shape of a story folder&quot;">​</a></h2><p>At the foot of the page, and in the side column, <strong>The shape of a story folder</strong> opens the guide&#39;s one page inside the app, in the app&#39;s language: the folder layout Leathercase reads best, shown on the sample story, the rules it reads by, a smaller shape for a short story, and what the reading cannot do (it splits scenes only at headings; it reads she and he back to the nearest name, but not an epithet; it reads Markdown, Word, Scrivener and Fountain; see <a href="/guide/reference/formats">Files Leathercase reads</a>). <strong>Back to how this story is read</strong> returns; <strong>Try the sample</strong> opens the sample library. The same page is offered at first run, under <strong>Wondering how Leathercase will read your folder?</strong></p><h2 id="the-questions-over-the-story-s-views" tabindex="-1">The questions over the story&#39;s views <a class="header-anchor" href="#the-questions-over-the-story-s-views" aria-label="Permalink to &quot;The questions over the story&#39;s views&quot;">​</a></h2><p>You do not have to open this page to be asked. Over every view of the story, a strip carries the same questions, one at a time:</p><ol><li>first the notice about a story declared before roles, with <strong>Keep this reading</strong>, <strong>Show me</strong> (which opens this page) and <strong>Later</strong>;</li><li>then the unsorted groups, the largest first, with the answers above, <strong>Don&#39;t ask again</strong> and <strong>Later</strong>, and how many more wait, such as <strong>2 more</strong>;</li><li>then, in a strip of its own, a rename waiting, with <strong>Yes, follow …</strong> and <strong>No, they are different</strong>.</li></ol><p><strong>Later</strong> hides the strip until Leathercase is opened again. The strips are not shown on this page or on the story&#39;s settings page, where the same questions are listed in full.</p><p><img src="'+d+'" alt="The strip over the plot grid asking what notes of type symbol are" width="1130" height="107" loading="lazy"></p>',75)),i(s,{name:"how-a-story-is-read-answer",caption:"Answering that notes of type symbol are things that recur, found by their images, named Symbol: the question goes and the notes are sorted"}),e[1]||(e[1]=t('<h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/declare-a-story">Declaring a story</a></li><li><a href="/guide/guide/homes-and-stories">Homes and stories</a></li><li><a href="/guide/guide/story-settings">Story settings</a></li><li><a href="/guide/guide/scaffold-a-story">Scaffold a story folder</a></li><li><a href="/guide/reference/front-matter">Front matter</a></li><li><a href="/guide/reference/formats">Files Leathercase reads</a></li><li><a href="/guide/guide/plot-grid">Plot grid</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>',2))])}const b=o(l,[["render",g]]);export{m as __pageData,b as default};
